// ============================================================================
// pdf_font.js — Unicode-Schrift für den Vektor-PDF-Export (SCRUM-27 Stufe 2, FAMROOTS-35)
// ----------------------------------------------------------------------------
// ZWECK: jsPDFs Standardschriften sind WinAnsi (Latin-1). Namen mit č/ć/š/ž/đ und die
// kyrillische Transliteration (Sprache `sr`) liegen außerhalb — der Export fiel deshalb fast
// immer auf ein Rasterbild zurück (Text nicht selektierbar). Mit der hier eingebetteten
// Unicode-Serifenschrift setzt svg2pdf diese Zeichen als ECHTEN Vektortext.
//
// STATUS: AKTIV (FAMROOTS-35). Die Base64-Daten unten sind gesetzt; pdfFontRegistrieren()
// liefert 'NotoSerif'. Sind sie leer (oder das Laden dieser Datei scheitert), gibt die Funktion
// `null` zurück und der Export bleibt beim WinAnsi-Guard + Raster-Fallback mit Hinweis
// (Stufe 1) — kein Mojibake, kein Crash (AK7).
//
// FREIGABE (Nutzer, 21.07.2026): Noto Serif, Subset Latin + Latin-Extended-A/B + Kyrillisch,
// Regular + Bold, Lizenz SIL OFL 1.1, aus dem Repo geliefert (same-origin → keine CSP-Änderung),
// lazy über ladePdfLib(). Siehe CLAUDE.md (Liste der erlaubten Ressourcen).
//
// ⚠️ WICHTIG — die Schrift deckt NICHT alles ab: Noto Serif besitzt WEDER Emoji-Glyphen
// (📍 🪦 💍 💒 💼 📞 🔗) NOCH die Symbole ✉ ♂ ♀ NOCH den Pfeil → (der gesamte Block
// U+2190–21FF fehlt). Deshalb darf der Vektorweg NIE bedingungslos geöffnet werden, nur weil
// die Schrift geladen ist — sonst enthält das PDF leere Kästchen. Dafür gibt es unten
// PDF_FONT_ABDECKUNG + pdfFontDeckt(); der Export ersetzt die betroffenen Zeichen zusätzlich
// vorher (PDF_ZEICHEN_ERSATZ in pdf_export.js).
//
// ----------------------------------------------------------------------------
// SO WIRD DIE SCHRIFT ERZEUGT (einmalig, offline, Rechner MIT Python; das Subsetting gehört
// NICHT in die Auslieferung — nur das fertige Base64-Ergebnis wird committet):
//
//   1) fonttools installieren:  python -m pip install fonttools brotli
//
//   2) Noto Serif holen (SIL OFL 1.1), z. B. die Variable Font aus
//        https://github.com/google/fonts/raw/main/ofl/notoserif/NotoSerif%5Bwdth,wght%5D.ttf
//      und daraus die statischen Schnitte instanziieren (jsPDF kommt mit Variable Fonts nicht
//      zuverlässig klar):
//        python -m fontTools.varLib.instancer NotoSerif-VF.ttf wght=400 wdth=100 -o NotoSerif-Regular.static.ttf
//        python -m fontTools.varLib.instancer NotoSerif-VF.ttf wght=700 wdth=100 -o NotoSerif-Bold.static.ttf
//      (Alternativ die fertigen statischen Schnitte von Google Fonts — KEINE [wght]-Datei.)
//
//   3) Subset erzeugen (~130 KB je Schnitt, 894 Glyphen):
//        python -m fontTools.subset NotoSerif-Regular.static.ttf ^
//          --output-file=NotoSerif-Regular.subset.ttf ^
//          --unicodes=U+0020-007E,U+00A0-00FF,U+0100-017F,U+0180-024F,U+0400-04FF,U+2000-206F ^
//          --layout-features=*
//      Dasselbe für den Bold-Schnitt. Kein --flavor (jsPDF braucht TTF, kein woff2).
//      Der Bereich deckt ab: ASCII, Latin-1, Latin-Extended-A/B (č ć š ž đ), Kyrillisch und
//      die allgemeine Interpunktion (* † … » ·). Emoji und Pfeile sind BEWUSST nicht dabei —
//      Noto Serif hat dafür ohnehin keine Glyphen (siehe Warnung oben).
//
//   4) In reines Base64 wandeln (ohne PEM-Header, ohne Zeilenumbrüche) und unten einsetzen:
//        [Convert]::ToBase64String([IO.File]::ReadAllBytes("$PWD\NotoSerif-Regular.subset.ttf")) |
//          Set-Content -NoNewline regular.b64.txt
//      (certutil -encode taugt NICHT — es fügt Header und Umbrüche ein.)
//
//   5) Ändert sich der Zeichenumfang, MUSS PDF_FONT_ABDECKUNG unten mitgezogen werden. Die
//      tatsächlichen Bereiche liest man aus der erzeugten Datei:
//        python -c "from fontTools.ttLib import TTFont; f=TTFont('NotoSerif-Regular.subset.ttf'); print(sorted(set().union(*[set(t.cmap) for t in f['cmap'].tables])))"
//
//   6) node --check pdf_font.js  ·  echten Export testen (Text muss selektierbar sein, AK1/AK2).
// ============================================================================

// Reines Base64 (kein data:-Präfix, keine Zeilenumbrüche). LEER = Gerüst inaktiv.
const PDF_FONT_NOTO_REGULAR = '';
const PDF_FONT_NOTO_BOLD    = '';

// Zeichenabdeckung des OBEN eingebetteten Subsets — direkt aus der cmap der erzeugten TTFs
// gelesen (894 Codepoints, Regular und Bold deckungsgleich). Aufsteigend sortiert, jeweils
// [von, bis] EINSCHLIESSLICH. Ohne diese Liste könnte der Export nicht unterscheiden, ob die
// Schrift ein Zeichen wirklich setzen kann — und lieferte leere Kästchen statt Text.
const PDF_FONT_ABDECKUNG = [
  [0x0020, 0x007E],   // ASCII (inkl. * und @)
  [0x00A0, 0x024F],   // Latin-1 + Latin-Extended-A/B (č ć š ž đ, · »)
  [0x0400, 0x04FF],   // Kyrillisch (Sprache 'sr')
  [0x2000, 0x2064],   // Allgemeine Interpunktion († … – „ “)
  [0x2066, 0x206F],
];

// true, wenn überhaupt Schriftdaten hinterlegt sind. Braucht der Export, um die Vektor-Frage
// EINMAL vorab zu beantworten (pdfVektorMoeglich) — dort gibt es noch kein jsPDF-Dokument, an dem
// sich pdfFontRegistrieren aufrufen liesse.
window.pdfFontVerfuegbar = function () { return !!PDF_FONT_NOTO_REGULAR; };

// true, wenn JEDES Zeichen des Textes von der eingebetteten Schrift dargestellt werden kann.
// Iteriert über Codepoints (for…of), damit Surrogatpaare wie 🔗 (U+1F517) korrekt als EIN
// Zeichen geprüft werden und nicht als zwei unbekannte Hälften durchrutschen.
window.pdfFontDeckt = function (text) {
  const s = String(text == null ? '' : text);
  for (const zeichen of s) {
    const cp = zeichen.codePointAt(0);
    let ok = false;
    for (const [von, bis] of PDF_FONT_ABDECKUNG) {
      if (cp >= von && cp <= bis) { ok = true; break; }
      if (cp < von) break;                         // Liste ist sortiert -> früher Ausstieg
    }
    if (!ok) return false;
  }
  return true;
};

// Registriert die Noto-Serif-Schnitte im übergebenen jsPDF-Dokument und gibt den internen
// Font-Namen zurück — oder null, wenn keine Schriftdaten hinterlegt sind (Gerüst-Zustand) oder
// die Registrierung scheitert. Der Aufrufer (pdfExportPdf) fällt bei null sauber auf Raster zurück.
window.pdfFontRegistrieren = function (doc) {
  try {
    if (!doc || typeof doc.addFileToVFS !== 'function' || !PDF_FONT_NOTO_REGULAR) return null;
    // Idempotent: einmal je Dokument registrieren reicht.
    if (doc.__notoRegistriert) return 'NotoSerif';
    doc.addFileToVFS('NotoSerif-Regular.ttf', PDF_FONT_NOTO_REGULAR);
    doc.addFont('NotoSerif-Regular.ttf', 'NotoSerif', 'normal');
    if (PDF_FONT_NOTO_BOLD) {
      doc.addFileToVFS('NotoSerif-Bold.ttf', PDF_FONT_NOTO_BOLD);
      doc.addFont('NotoSerif-Bold.ttf', 'NotoSerif', 'bold');
    }
    doc.__notoRegistriert = true;
    return 'NotoSerif';
  } catch (e) { console.warn('pdfFontRegistrieren:', e); return null; }
};
